package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.MovimentoEstoque; import java.util.*; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.*; public interface MovimentoEstoqueRepository extends JpaRepository<MovimentoEstoque,String> { @Query("select m from MovimentoEstoque m join fetch m.produto order by m.dataMovimento desc") List<MovimentoEstoque> recent(Pageable limit); }
